var root = get_tree().edited_scene_root
var ps = load("res://scenes/rigs/mobs/rig_mob_d2_skeleton.tscn")
var inst = ps.instantiate()
inst.name = "DraxP1Skeleton"
root.add_child(inst)
inst.owner = root
# compute combined aabb of MeshInstance3D descendants
var aabb = AABB()
var first = true
var stack = [inst]
var meshcount = 0
while stack.size() > 0:
	var n = stack.pop_back()
	if n is MeshInstance3D and n.mesh != null:
		meshcount += 1
		var world_aabb = n.global_transform * n.get_aabb()
		if first:
			aabb = world_aabb
			first = false
		else:
			aabb = aabb.merge(world_aabb)
	for c in n.get_children():
		stack.push_back(c)
_mcp_print("instanced: " + inst.name)
_mcp_print("mesh_instances: " + str(meshcount))
_mcp_print("aabb_size: " + str(aabb.size))
_mcp_print("aabb_center: " + str(aabb.get_center()))
